SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `instruments`;
CREATE TABLE `instruments` (
  `serial_number` varchar(100) NOT NULL COMMENT '儀器序號 S/N',
  `instrument_name` varchar(200) NOT NULL,
  `group_id` char(36) NOT NULL COMMENT 'FK → lab_group.group_id',
  `machine_role` varchar(20) NOT NULL DEFAULT '主機' COMMENT '主機 / 備機',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`serial_number`),
  KEY `idx_instruments_group` (`group_id`),
  CONSTRAINT `fk_instruments_group` FOREIGN KEY (`group_id`) REFERENCES `lab_group` (`group_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `items`;
CREATE TABLE `items` (
  `item_id` char(36) NOT NULL DEFAULT uuid(),
  `instrument_serial_number` varchar(100) NOT NULL COMMENT 'FK → instruments.serial_number (此項目屬於哪台儀器)',
  `group_id` char(36) DEFAULT NULL COMMENT 'FK → lab_group.group_id',
  `item_code` varchar(50) NOT NULL COMMENT '項目代碼，如 RBC / HGB / WBC / NEUT%',
  `item_name` varchar(200) DEFAULT NULL COMMENT '項目全名',
  `unit` varchar(50) DEFAULT NULL,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `remark` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`item_id`),
  UNIQUE KEY `uq_items_instrument_code` (`instrument_serial_number`,`item_code`),
  KEY `idx_items_group` (`group_id`),
  CONSTRAINT `fk_items_group` FOREIGN KEY (`group_id`) REFERENCES `lab_group` (`group_id`),
  CONSTRAINT `fk_items_instrument` FOREIGN KEY (`instrument_serial_number`) REFERENCES `instruments` (`serial_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `lab_group`;
CREATE TABLE `lab_group` (
  `group_id` char(36) NOT NULL DEFAULT uuid(),
  `group_name` varchar(50) NOT NULL COMMENT '組別名稱，例如 生化免疫組 / 血液組 / 鏡檢組 / 血庫組',
  `group_code` varchar(20) DEFAULT NULL COMMENT '組別代碼 (選填)',
  `description` varchar(255) DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`group_id`),
  UNIQUE KEY `group_name` (`group_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `qc_reagent_map`;
CREATE TABLE `qc_reagent_map` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `reagent_qc_id` char(36) NOT NULL COMMENT 'FK → reagent_qc.reagent_qc_id',
  `reagent_id` char(36) NOT NULL COMMENT 'FK → reagent.reagent_id',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_qc_reagent` (`reagent_qc_id`,`reagent_id`),
  KEY `idx_qcmap_reagent` (`reagent_id`),
  CONSTRAINT `fk_qcmap_reagent` FOREIGN KEY (`reagent_id`) REFERENCES `reagent` (`reagent_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_qcmap_rqc` FOREIGN KEY (`reagent_qc_id`) REFERENCES `reagent_qc` (`reagent_qc_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=39 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `qc_records`;
CREATE TABLE `qc_records` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `reagent_qc_id` char(36) DEFAULT NULL COMMENT 'FK → reagent_qc.reagent_qc_id (此筆品管使用的品管液)',
  `group_id` char(36) DEFAULT NULL COMMENT 'FK → lab_group.group_id',
  `instrument_serial_number` varchar(100) NOT NULL COMMENT 'FK → instruments.serial_number',
  `instrument_name` varchar(200) NOT NULL,
  `test_item` varchar(100) NOT NULL,
  `test_item_full_name` varchar(200) DEFAULT NULL,
  `qc_level` varchar(50) DEFAULT NULL,
  `qc_lot_number` varchar(100) DEFAULT NULL,
  `unit` varchar(50) DEFAULT NULL,
  `lot_mean` decimal(15,4) DEFAULT NULL COMMENT '本次採用的均值 (快照)',
  `lot_standard_deviation` decimal(15,6) DEFAULT NULL COMMENT '本次採用的 SD (快照)',
  `acceptable_range_lower` decimal(15,4) DEFAULT NULL,
  `acceptable_range_upper` decimal(15,4) DEFAULT NULL,
  `qc_date` date NOT NULL,
  `qc_time` time NOT NULL,
  `operator` varchar(100) DEFAULT NULL,
  `qc_result_value` decimal(15,4) DEFAULT NULL,
  `z_score` decimal(10,2) DEFAULT NULL,
  `qc_status` varchar(20) NOT NULL DEFAULT 'Pass' COMMENT 'Pass / Warning / Fail',
  `westgard_rule_violation` text DEFAULT NULL,
  `remark` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_qc_date` (`qc_date`),
  KEY `idx_qc_instrument` (`instrument_serial_number`),
  KEY `idx_qc_group` (`group_id`),
  KEY `idx_qc_rqc` (`reagent_qc_id`),
  KEY `idx_qc_item` (`test_item`),
  KEY `idx_qc_sn_item_level` (`instrument_serial_number`,`test_item`,`qc_level`),
  CONSTRAINT `fk_qc_group` FOREIGN KEY (`group_id`) REFERENCES `lab_group` (`group_id`),
  CONSTRAINT `fk_qc_instrument` FOREIGN KEY (`instrument_serial_number`) REFERENCES `instruments` (`serial_number`),
  CONSTRAINT `fk_qc_rqc` FOREIGN KEY (`reagent_qc_id`) REFERENCES `reagent_qc` (`reagent_qc_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `reagent`;
CREATE TABLE `reagent` (
  `reagent_id` char(36) NOT NULL DEFAULT uuid(),
  `group_id` char(36) DEFAULT NULL COMMENT 'FK → lab_group.group_id',
  `instrument_serial_number` varchar(100) DEFAULT NULL COMMENT 'FK → instruments.serial_number (此試劑用於哪台儀器)',
  `test_item` varchar(100) NOT NULL COMMENT '對應檢驗項目，如 GLU / WBC',
  `reagent_name` varchar(200) NOT NULL,
  `lot_number` varchar(100) NOT NULL COMMENT '試劑批號',
  `manufacturer` varchar(200) DEFAULT NULL,
  `in_stock` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已入庫',
  `in_stock_date` date DEFAULT NULL COMMENT '入庫日期',
  `parallel_test_done` tinyint(1) NOT NULL DEFAULT 0 COMMENT '入庫後是否已完成試劑平行測試 (平測)',
  `parallel_test_date` date DEFAULT NULL COMMENT '試劑平測完成日期',
  `same_lot_as_previous` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否與上一個批號為同一批號',
  `previous_lot_number` varchar(100) DEFAULT NULL COMMENT '上一個批號 (供批號延續性追溯)',
  `expiry_date` date DEFAULT NULL COMMENT '效期',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `remark` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`reagent_id`),
  KEY `idx_reagent_group` (`group_id`),
  KEY `idx_reagent_instrument` (`instrument_serial_number`),
  KEY `idx_reagent_item` (`test_item`),
  KEY `idx_reagent_lot` (`lot_number`),
  CONSTRAINT `fk_reagent_group` FOREIGN KEY (`group_id`) REFERENCES `lab_group` (`group_id`),
  CONSTRAINT `fk_reagent_instrument` FOREIGN KEY (`instrument_serial_number`) REFERENCES `instruments` (`serial_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `reagent_item_map`;
CREATE TABLE `reagent_item_map` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `reagent_id` char(36) NOT NULL COMMENT 'FK → reagent.reagent_id',
  `item_id` char(36) NOT NULL COMMENT 'FK → items.item_id',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_reagent_item` (`reagent_id`,`item_id`),
  KEY `idx_rimap_item` (`item_id`),
  CONSTRAINT `fk_rimap_item` FOREIGN KEY (`item_id`) REFERENCES `items` (`item_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_rimap_reagent` FOREIGN KEY (`reagent_id`) REFERENCES `reagent` (`reagent_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `reagent_qc`;
CREATE TABLE `reagent_qc` (
  `reagent_qc_id` char(36) NOT NULL DEFAULT uuid(),
  `group_id` char(36) DEFAULT NULL COMMENT 'FK → lab_group.group_id',
  `instrument_serial_number` varchar(100) DEFAULT NULL COMMENT 'FK → instruments.serial_number',
  `specimen_type_id` char(36) DEFAULT NULL,
  `test_item` varchar(100) NOT NULL,
  `test_item_full_name` varchar(200) DEFAULT NULL,
  `qc_level` varchar(50) NOT NULL COMMENT '品管液濃度，如 Level 1 / Level 2 / Level 3',
  `qc_lot_number` varchar(100) DEFAULT NULL COMMENT '目前使用中的批號；設定檔尚未進批時為 NULL',
  `expiry_date` date DEFAULT NULL COMMENT '目前批號效期',
  `lot_received_date` date DEFAULT NULL COMMENT '目前批號到貨/啟用日',
  `unit` varchar(50) DEFAULT NULL,
  `manufacturer_mean` decimal(15,4) DEFAULT NULL COMMENT '原廠 (或前批) 均值',
  `manufacturer_sd` decimal(15,6) DEFAULT NULL COMMENT '原廠 (或前批) SD',
  `parallel_test_done` tinyint(1) NOT NULL DEFAULT 0 COMMENT '此品管液是否已完成平行測試',
  `parallel_test_date` date DEFAULT NULL COMMENT '平行測試完成日期',
  `new_standard_mean` decimal(15,4) DEFAULT NULL COMMENT '平行測試後建立的新 standard mean',
  `new_standard_sd` decimal(15,6) DEFAULT NULL COMMENT '平行測試後建立的新 standard SD',
  `in_use` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否為目前使用中的品管液',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `remark` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`reagent_qc_id`),
  UNIQUE KEY `uq_rqc_profile` (`instrument_serial_number`,`test_item`,`qc_level`,`specimen_type_id`),
  KEY `idx_rqc_group` (`group_id`),
  KEY `idx_rqc_instrument` (`instrument_serial_number`),
  KEY `idx_rqc_item_level` (`test_item`,`qc_level`),
  KEY `idx_rqc_lot` (`qc_lot_number`),
  KEY `idx_rqc_specimen` (`specimen_type_id`),
  CONSTRAINT `fk_rqc_group` FOREIGN KEY (`group_id`) REFERENCES `lab_group` (`group_id`),
  CONSTRAINT `fk_rqc_instrument` FOREIGN KEY (`instrument_serial_number`) REFERENCES `instruments` (`serial_number`),
  CONSTRAINT `fk_rqc_specimen` FOREIGN KEY (`specimen_type_id`) REFERENCES `specimen_type` (`specimen_type_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `reagent_qc_lot`;
CREATE TABLE `reagent_qc_lot` (
  `lot_id` char(36) NOT NULL DEFAULT uuid(),
  `reagent_qc_id` char(36) NOT NULL COMMENT 'FK → reagent_qc.reagent_qc_id (所屬設定檔)',
  `qc_lot_number` varchar(100) NOT NULL,
  `manufacturer_mean` decimal(15,4) DEFAULT NULL,
  `manufacturer_sd` decimal(15,6) DEFAULT NULL,
  `new_standard_mean` decimal(15,4) DEFAULT NULL,
  `new_standard_sd` decimal(15,6) DEFAULT NULL,
  `parallel_test_done` tinyint(1) NOT NULL DEFAULT 0,
  `parallel_test_date` date DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `effective_from` date DEFAULT NULL COMMENT '啟用日',
  `effective_to` date DEFAULT NULL COMMENT '停用日；NULL 表示仍在使用',
  `is_current` tinyint(1) NOT NULL DEFAULT 1,
  `remark` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`lot_id`),
  UNIQUE KEY `uq_qc_lot` (`reagent_qc_id`,`qc_lot_number`),
  KEY `idx_qclot_current` (`reagent_qc_id`,`is_current`),
  CONSTRAINT `fk_qclot_rqc` FOREIGN KEY (`reagent_qc_id`) REFERENCES `reagent_qc` (`reagent_qc_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `reagent_specimen_map`;
CREATE TABLE `reagent_specimen_map` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `reagent_id` char(36) NOT NULL,
  `specimen_type_id` char(36) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_reagent_specimen` (`reagent_id`,`specimen_type_id`),
  KEY `idx_rsmap_specimen` (`specimen_type_id`),
  CONSTRAINT `fk_rsmap_reagent` FOREIGN KEY (`reagent_id`) REFERENCES `reagent` (`reagent_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_rsmap_specimen` FOREIGN KEY (`specimen_type_id`) REFERENCES `specimen_type` (`specimen_type_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `specimen_type`;
CREATE TABLE `specimen_type` (
  `specimen_type_id` char(36) NOT NULL DEFAULT uuid(),
  `code` varchar(20) NOT NULL,
  `name` varchar(100) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`specimen_type_id`),
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

